#!/usr/bin/env python3
"""Check that every number the README quotes matches the committed source.

The README is written by hand, so it is the one place a number can drift away
from the result it describes. This reads the committed summaries and rebuilds,
from them, each fragment of the README that quotes a number, then fails if the
README does not contain that fragment exactly:

* the reference-simulation comparison, from ``docs/RESULTS.md`` (generated by
  ``analysis/make_results.py``);
* the PX4 SITL table, from ``sitl/results/summary.json`` (generated by
  ``analysis/make_sitl_results.py``), which must match byte for byte;
* the estimator and QP figures, from ``docs/ESTIMATOR.md`` and
  ``docs/CONTROLLERS.md``;
* the measured PX4 command delay and the reference-gain flights quoted in
  ``sitl/README.md``, from ``mission_control.sitl`` and the summary.

It needs no simulation and runs in a second, so CI runs it on every push.
"""

from __future__ import annotations

import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "src"))

from mission_control import sitl  # noqa: E402


def read(relative: str) -> str:
    with open(os.path.join(ROOT, relative), encoding="utf-8") as handle:
        return handle.read()


def find(pattern: str, text: str, source: str) -> tuple:
    match = re.search(pattern, text)
    if not match:
        raise ValueError(f"{source}: could not find {pattern!r}")
    return match.groups()


def reference_claims(results: str) -> list:
    """README fragments implied by docs/RESULTS.md."""
    src = "docs/RESULTS.md"
    runs, scenarios = find(r"(\d+) runs: (\d+) scenarios", results, src)
    wins, pairs, ratio = find(
        r"\*\*(\d+) of (\d+) paired scenarios go to the MPC\*\*, with a median error "
        r"ratio of ([\d.]+)x", results, src)
    rms = find(r"Mean RMS position error: \*\*PID ([\d.]+) m\*\*, \*\*MPC ([\d.]+) m\*\*",
               results, src)
    cross = find(r"Mean cross-track error: PID ([\d.]+) m, MPC ([\d.]+) m", results, src)
    jerk = find(r"acceleration demand: PID ([\d.]+) m/s\^3, MPC ([\d.]+) m/s\^3", results, src)
    tuned = find(r"\| Tuned on \| \d+ \| \d+ \| ([\d.]+)x \|", results, src)[0]
    held = find(r"\| Held out \| \d+ \| \d+ \| ([\d.]+)x \|", results, src)[0]
    infeasible = find(r"Infeasible reference \(sharp corners\)\*\* .*?median ratio ([\d.]+)x",
                      results, src)[0]
    sat_pid, sat_mpc = find(
        r"\| `corridor survey \(sharp corners\)` nominal/calm \| (\d+%) \| (\d+%) \|",
        results, src)
    facade = find(r"\| `facade inspection` \| yes \| nominal \| calm \| \**([\d.]+)\** m \| "
                  r"\**([\d.]+)\** m \|", results, src)
    facade_fast_gusty = find(r"\| `facade inspection` \| held out \| fast \| gusty \|.*?\| "
                             r"(PID|MPC) \|", results, src)[0]
    pid_cost = find(r"\| PID \| ([\d.]+) us \| ([\d.]+) us \|", results, src)
    mpc_cost = find(r"\| MPC \| ([\d.]+) us \| ([\d.]+) us \|", results, src)

    def m3(value):
        return f"{float(value):.3f} m"

    claims = [
        f"Across {runs} runs",
        f"{scenarios} scenarios",
        f"**{wins} of {pairs} paired scenarios go to the MPC**, at a median error ratio "
        f"of {ratio}×",
        f"| Mean RMS position error | {m3(rms[0])} | **{m3(rms[1])}** |",
        f"| Mean cross-track error | {m3(cross[0])} | **{m3(cross[1])}** |",
        f"| Mean RMS jerk of the acceleration demand | {float(jerk[0]):.1f} m/s³ | "
        f"**{float(jerk[1]):.1f} m/s³** |",
        f"| Optimisation per control step | {float(pid_cost[0]):.0f} µs | "
        f"{float(mpc_cost[0]):.0f} µs |",
        f"| Whole control step | {float(pid_cost[1]):.0f} µs | {float(mpc_cost[1]):.0f} µs |",
        f"({held}× against {tuned}×)",
        f"it is **{infeasible}×**",
        f"PID spends **{sat_pid} of the mission at a limit and the MPC {sat_mpc}**",
        f"{m3(facade[0])} against {m3(facade[1])}",
        f"at {float(jerk[1]):.1f} m/s³ of demand jerk against {float(jerk[0]):.1f}",
    ]
    if facade_fast_gusty == "PID":
        claims.append("facade, fast, gusty, goes to the PID outright")
    return claims


def benchmark_claims(estimator: str, controllers: str) -> list:
    naive = find(r"\| Fusing each fix as though it were current \| ([\d.]+ m) \|",
                 estimator, "docs/ESTIMATOR.md")[0]
    compensated = find(r"\| Fusion horizon plus output predictor \| ([\d.]+ m) \|",
                       estimator, "docs/ESTIMATOR.md")[0]
    warm = find(r"\| warm-started from the previous step \| ([\d.]+) us \|",
                controllers, "docs/CONTROLLERS.md")[0]
    kkt = find(r"KKT residual of ([\d.e+-]+) at the solution", controllers,
               "docs/CONTROLLERS.md")[0]
    return [
        f"**{naive} to {compensated} position RMS**",
        f"**{warm} µs per axis warm-started, KKT residual {kkt}**",
    ]


def sitl_readme_claims(summary: dict) -> list:
    """sitl/README.md fragments implied by the SITL summary and constants."""
    delay, lag = sitl.PX4_SIH_COMMAND_DELAY_S, sitl.PX4_SIH_LAG_TAU_S
    claims = [
        f"**{delay:.2f} s delay and a {lag:.2f} s lag**",
        f"{delay + lag:.2f} s, the same way the reference MPC's",
    ]
    transfer = {flight["tracker"]: flight for flight in summary.get("transfer", [])}
    if "mpc" in transfer:
        claims.append(f"the MPC flew the facade survey at {transfer['mpc']['rms_error_m']:.2f} m")
    if "pid" in transfer:
        pid = transfer["pid"]
        claims.append(f"PX4's EKF {pid['rms_estimation_error_m']:.1f} m RMS away from the truth")
        claims.append(f"mission {pid['rms_error_m']:.1f} m RMS from its path")
    return claims


def check(readme: str, results: str, estimator: str, controllers: str,
          sitl_summary: dict, sitl_readme: str = None) -> list:
    problems = []
    if sitl_readme is not None:
        for claim in sitl_readme_claims(sitl_summary):
            if " ".join(claim.split()) not in " ".join(sitl_readme.split()):
                problems.append(f"sitl/README.md does not say: {claim}")
    for claim in reference_claims(results) + benchmark_claims(estimator, controllers):
        if claim not in readme:
            problems.append(f"README does not say: {claim}")
    expected = sitl.readme_sitl_block(sitl_summary)
    actual = sitl.extract_block(readme)
    if not actual:
        problems.append("README has no generated SITL table")
    elif actual != expected:
        problems.append(
            "README SITL table differs from sitl/results/summary.json; run "
            "`python analysis/make_sitl_results.py --write-readme`"
        )
    return problems


def main() -> int:
    with open(os.path.join(ROOT, "sitl", "results", "summary.json"), encoding="utf-8") as handle:
        summary = json.load(handle)
    problems = check(read("README.md"), read("docs/RESULTS.md"), read("docs/ESTIMATOR.md"),
                     read("docs/CONTROLLERS.md"), summary, read("sitl/README.md"))
    if problems:
        print("README check FAILED:")
        for problem in problems:
            print(f"  {problem}")
        return 1
    print("README check passed: every quoted number matches its committed source")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
